 53→			loadTask(taskRef);
 54→		} else if (!open) {
 55→			task = null;
 56→			error = '';
 57→			actionError = '';
 58→			noteContent = '';
 59→			reasonInput = '';
 60→			showReasonFor = null;
 61→		}
 62→	});
 63→
 64→	async function loadTask(ref: string) {
 65→		loading = true;
