   356→  errors: Array<{
   357→    file: string;
   358→    message: string;
   359→    path?: string;
   360→  }>;
   361→  warnings: Array<{
   362→    file: string;
   363→    message: string;
   364→  }>;
   365→}
   366→
   367→/**
