        await commitIfShadow(ctx.shadow, `task: block ${params.ref}`);

        pubsub.broadcast('tasks:updates', 'task_updated', {
          ref: params.ref,
          ulid: task._ulid,
          action: 'block',
          status: 'blocked',
        }, projectContext.path);

        return updatedTask;
      },
      {
        params: t.Object({ ref: t.String() }),
        body: t.Object({ reason: t.String() }),
      }
    );
}

